import Foundation
import Observation

@MainActor
@Observable
final class TeamDirectoryModel {
    private let api: ProfileAPI
    var profiles: [Profile] = []
    var error: Error?

    init(api: ProfileAPI) { self.api = api }

    func load(memberIDs: [Profile.ID]) async {
        do {
            var loaded: [Profile] = []
            for id in memberIDs {
                let profile = try await api.fetchProfile(id: id)
                loaded.append(profile)
            }
            profiles = loaded
        } catch {
            self.error = error
        }
    }
}

import Foundation

@MainActor
final class DashboardViewModel: ObservableObject {
    @Published private(set) var state: DashboardState = .loading
    private let api: DashboardAPI

    init(api: DashboardAPI) { self.api = api }

    func refresh(accountID: String) async {
        do {
            let balance = try await api.balance(accountID: accountID)
            let transactions = try await api.recentTransactions(accountID: accountID, limit: 20)
            let alerts = try await api.alerts(accountID: accountID)
            state = .loaded(balance: balance, transactions: transactions, alerts: alerts)
        } catch {
            state = .failed(error.localizedDescription)
        }
    }
}

