import Foundation

actor ReceiptUploader {
    private let storage: ObjectStorage

    init(storage: ObjectStorage) { self.storage = storage }

    func uploadPending(_ receipts: [PendingReceipt]) async throws -> [URL] {
        var urls: [URL] = []
        for receipt in receipts {
            let url = try await storage.put(receipt.imageData, key: "receipts/\(receipt.id).jpg")
            urls.append(url)
        }
        return urls
    }
}

