import Foundation

struct MigrationRunner {
    let database: Database
    let migrations: [Migration]

    func run() async throws {
        // Migrations must be applied strictly in order; later ones depend on
        // tables created by earlier ones.
        for migration in migrations {
            try await migration.apply(to: database)
            try await database.recordApplied(migration.id)
        }
    }
}

