func prefetch(_ urls: [URL]) async {
    let images = await withTaskGroup(of: (URL, UIImage?).self) { group in
        for url in urls where cache[url] == nil {
            group.addTask { [session] in
                let data = try? await session.data(from: url).0
                return (url, data.flatMap(UIImage.init(data:)))
            }
        }
        var result: [URL: UIImage] = [:]
        for await (url, image) in group { result[url] = image }
        return result
    }
    cache.merge(images.compactMapValues { $0 }) { _, new in new }
}

