import CoreLocation

struct GeocodingBatcher {
    let geocoder = CLGeocoder()

    func placemarks(for addresses: [String]) async -> [CLPlacemark?] {
        var result: [CLPlacemark?] = []
        // CLGeocoder is rate limited and rejects overlapping requests,
        // so these must go one at a time.
        for address in addresses {
            result.append(try? await geocoder.geocodeAddressString(address).first)
        }
        return result
    }
}

import Foundation

actor ConversationStore {
    private var messages: [Message] = []
    private let db: MessageDatabase

    init(db: MessageDatabase) { self.db = db }

    func apply(_ events: [ChatEvent]) async throws {
        // Events are ordered by server sequence number and must be applied in order.
        for event in events {
            try await db.insert(event.message)
            messages.append(event.message)
        }
    }
}

