import Foundation

enum CSVParser {
    static func rows(from text: String, separator: Character = ",") -> [[String]] {
        text.split(whereSeparator: \.isNewline).map { line in
            line.split(separator: separator, omittingEmptySubsequences: false)
                .map { $0.trimmingCharacters(in: .whitespaces) }
        }
    }
}

import Foundation

actor TokenRefresher {
    private var current: Token?
    private var inFlight: Task<Token, Error>?
    private let api: AuthAPI

    init(api: AuthAPI) { self.api = api }

    func validToken() async throws -> Token {
        if let current, !current.isExpired { return current }
        if let inFlight { return try await inFlight.value }
        let task = Task { try await api.refresh() }
        inFlight = task
        defer { inFlight = nil }
        let token = try await task.value
        current = token
        return token
    }
}

